"""Runs only in the no-network Windows Sandbox generated by windows_host.py."""
import ctypes
import json
import os
from pathlib import Path
import subprocess
import sys


def main():
    reply={'status':'blocked','code':'isolation_failed','cloud_release':False}
    try:
        if sys.platform!='win32':return 2
        out=Path(r'C:\PrivacyOutput')
        config=json.loads(Path(r'C:\PrivacyControl\request.json').read_text(encoding='utf-8'))
        skill=Path(r'C:\PrivacySkill')
        env={k:os.environ[k] for k in ['SystemRoot','WINDIR','PATH','TEMP','TMP','USERNAME','USERPROFILE','LOCALAPPDATA'] if k in os.environ}
        env['PYTHONDONTWRITEBYTECODE']='1'
        if config['mode']=='demo':
            # Synthetic fixture only. Its subprocesses must pass the real OS check.
            cmd=[sys.executable,'-I','-B',str(skill/'tests/make_demo.py'),str(out/'fictional-demo')]
        else:
            cmd=[sys.executable,'-I','-B',str(skill/'scripts/run_local.py'),'--mode',config['mode'],'--input',config['input'],'--policy',config['policy'],'--out',str(out/'result')]
            if config['mode']=='prepare-import':
                cmd+=['--job',config['job'],'--results',config['results'],'--import-policy',config['import_policy']]
        if config['mode']=='prepare-summary':
                cmd+=['--job',config['job'],'--summary-policy',config['summary_policy']]
        result=subprocess.run(cmd,env=env,capture_output=True,text=True,encoding='utf-8',timeout=120)
        if config['mode']=='demo':
            data=json.loads(result.stdout)
            if result.returncode==0 and data.get('all_checked_values_equal') is True and data.get('local_restoration',{}).get('identity_and_value_matches')==60 and data.get('derived_subset',{}).get('exact_identity_and_value_match') is True and data.get('derived_subset',{}).get('rows')==21:
                reply={'status':'local_ready','code':'synthetic_demo_passed','cloud_release':False,'network_denied':True,'integrity_passed':True,'real_system_submitted':False}
        else:
            data=json.loads(result.stdout)
            if data.get('status')=='local_ready' and result.returncode==0:
                reply={k:data[k] for k in ['status','code','cloud_release','network_denied','integrity_passed']}
            elif data.get('status')=='blocked':reply['code']='processing_blocked'
        (out/'receipt.json').write_text(json.dumps(reply,indent=2),encoding='utf-8')
    except Exception:
        pass
    if sys.platform=='win32':
        ok=reply['status']=='local_ready'
        ctypes.windll.user32.MessageBoxW(None,'本地处理与检查完成。结果留在主机输出文件夹。汇总模式请在本地打开 summary-review.txt；本人检查并确认用途后，仅提供所需汇总JSON，不上传整个 private 文件夹。' if ok else '检查未通过，已停止。请勿跳过断网检查或改用联网主机直接处理。','本地表格隐私工具',0x40 if ok else 0x10)
    return 0 if reply['status']=='local_ready' else 2


if __name__=='__main__':sys.exit(main())
